<script>
  import { onMount } from 'svelte'

  let klass = ''
  export { klass as class }
  export let options = {}
  export let content = []

  const defaultOoptions = {
    deleteSpeed: 25, // ms
    writeSpeed: 35, // ms
    pauseBeforeWriting: 250, // ms
    pauseBeforeDeleting: 1000, // ms
  }

  const { deleteSpeed, writeSpeed, pauseBeforeWriting, pauseBeforeDeleting } = {
    ...defaultOoptions,
    ...options,
  }

  let phase = 0
  let contentToDisplay = content[phase]
  let displayedContent = contentToDisplay // Initial value

  onMount(() => {
    backspaceEffect()
  })

  function backspaceEffect() {
    // If there are any characters left to remove, remove them
    if (displayedContent.length) {
      setTimeout(() => {
        displayedContent = displayedContent.slice(0, -1)
        backspaceEffect()
      }, deleteSpeed)
    } else {
      // If there are no characters left to remove, we begin writing characters, but after a delay.
      setTimeout(() => {
        // Get the right set of words to display
        phase += 1
        if (!content[phase]) phase = 0
        contentToDisplay = content[phase]

        writeEffect()
      }, pauseBeforeWriting)
    }
  }

  function writeEffect() {
    setTimeout(_ => {
      const index = displayedContent.length || 0
      displayedContent = displayedContent + contentToDisplay[index]

      // Write until we've written all the characters
      if (displayedContent.length !== contentToDisplay.length) {
        writeEffect()
        return
      }

      // Pause for a bit before we start backspacing
      setTimeout(_ => {
        backspaceEffect()
      }, pauseBeforeDeleting)
    }, writeSpeed)
  }
</script>

<span class="Typewriter {klass}">
  {displayedContent}
</span>
